suppressPackageStartupMessages({
  library(ggVennDiagram)
})
# Print source of ggVennDiagram to find the failing call
body_text <- paste(deparse(body(ggVennDiagram)), collapse = "\n")
cat(body_text)

suppressPackageStartupMessages({
  library(readxl)
  library(ggVennDiagram)
})
path <- "inputs/set-membership-111111111111.xlsx"
df <- read_excel(path, sheet = "5 groups", col_names = TRUE)
sets <- lapply(colnames(df), function(c) unique(na.omit(df[[c]])))
names(sets) <- colnames(df)
# Bare minimum call
tryCatch({
  p_min <- ggVennDiagram(sets)
  cat("Bare call OK. Class:", class(p_min), "\n")
}, error = function(e) cat("Bare call error:", conditionMessage(e), "\n"))

suppressPackageStartupMessages({
  library(readxl)
  library(ggVennDiagram)
})
path <- "inputs/set-membership-111111111111.xlsx"
df <- read_excel(path, sheet = "5 groups", col_names = TRUE)
sets <- lapply(colnames(df), function(c) unique(na.omit(df[[c]])))
names(sets) <- colnames(df)
# Test with each potentially problematic argument, one at a time
tests <- list(
  list(label_size = 3.0),
  list(set_size = 4.5),
  list(set_color = "grey20"),
  list(label_percent_digit = 1),
  list(label_alpha = 0)
)
for (args in tests) {
  res <- tryCatch({
    do.call(ggVennDiagram, c(list(sets), args))
    "OK"
  }, error = function(e) conditionMessage(e))
  cat(sprintf("Args %s -> %s\n", paste(names(args), unlist(args), sep="=", collapse=", "), res))
}
